function pdfBase(titulo:string,subtitulo:string,cor:string,corpo:string){const hoje=new Date().toLocaleDateString('pt-BR',{day:'2-digit',month:'long',year:'numeric'});const empObj=(dados.empresas||[]).find((e:any)=>e.nome===usuario?.empresa)||{};const empNome=usuario?.empresa&&usuario.empresa!=='Todas'?usuario.empresa:tecnico.empresaLaudo||empObj.nome||'Empresa';return '<html><head><meta charset="utf-8"><title>'+titulo+' - PREVIX SST</title><style>@page{margin:14mm}*{box-sizing:border-box}body{font-family:Arial,sans-serif;margin:0;color:#0f172a;font-size:13px;line-height:1.5}.topo{background:linear-gradient(90deg,#0d9488,#2563eb);color:#fff;padding:22px 28px;display:flex;justify-content:space-between;align-items:center}.logo{font-size:26px;font-weight:900}.logo span{color:#a7f3d0}.slogan{font-size:10px;letter-spacing:3px;font-weight:700}.topo-dir{text-align:right;font-size:11px}.faixa{background:'+cor+';color:#fff;padding:10px 28px;font-weight:900;font-size:15px}.wrap{padding:22px 28px}.titulo{font-size:22px;font-weight:900;margin:4px 0 2px}.sub{color:#64748b;font-size:12px;margin-bottom:16px}.card{border:1px solid #e2e8f0;border-radius:14px;padding:16px;background:#f8fafc;margin-bottom:14px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.grid div{background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:10px}.grid small{color:#64748b;font-size:11px;text-transform:uppercase;font-weight:800}table{width:100%;border-collapse:collapse;margin:10px 0}th{background:#0f172a;color:#fff;padding:10px;text-align:left;font-size:12px}td{padding:10px;border-bottom:1px solid #e2e8f0;font-size:12px}.badge{display:inline-block;padding:4px 10px;border-radius:20px;font-weight:800;font-size:11px}.assinaturas{display:flex;justify-content:space-between;gap:20px;margin-top:36px;text-align:center}.assinaturas .linha{border-top:1.5px solid #0f172a;padding-top:8px;flex:1}.assinaturas small{color:#64748b}.rodape{margin-top:22px;border-top:1px solid #e2e8f0;padding-top:12px;font-size:11px;color:#64748b;display:flex;justify-content:space-between}.nota{background:#fef9c3;border:1px solid #fde68a;border-radius:10px;padding:12px;font-size:12px;margin:12px 0}.btnprint{background:#0d9488;color:#fff;border:none;padding:12px 22px;border-radius:20px;font-weight:900;cursor:pointer}@media print{.no-print{display:none!important}.topo,.faixa,th{-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style></head><body><div class="topo"><div><div class="logo">PREVIX <span>SST</span></div><div class="slogan">PREVENÇÃO QUE PROTEGE</div></div><div class="topo-dir"><b>Documento Oficial</b><br>Maceió - AL<br>'+hoje+'<br>(82) 99414-5622</div></div><div class="faixa">'+titulo+'</div><div class="wrap"><div class="titulo">'+titulo+'</div><div class="sub">'+subtitulo+' • Empresa: '+empNome+' • Emitido em '+hoje+'</div>'+corpo+'<div class="assinaturas"><div class="linha"><b>'+tecnico.nome+'</b><br><small>'+tecnico.formacao+' • CREA: '+(tecnico.crea||'-')+' • ART: '+(tecnico.art||'-')+' • MTE: '+(tecnico.mte||'-')+'</small><br><small>Responsável Técnico</small></div><div class="linha"><b>'+empNome+'</b><br><small>CNPJ: '+(empObj.cnpj||tecnico.cnpj||'-')+'</small><br><small>Empresa / Representante Legal</small></div></div><div class="rodape"><span>PREVIX SST • contato@previxsst.com.br</span><span>Documento gerado pelo PREVIX SST</span></div><div class="no-print" style="text-align:center;margin-top:20px"><button class="btnprint" onclick="window.print()">Imprimir / Salvar como PDF</button></div></div></body></html>'}
function gerarLaudo(tipo:string){const riscos=dadosFiltrados(dados.riscos||[]);const funcs=dadosFiltrados(dados.funcionarios||[]);const empObj=(dados.empresas||[]).find((e:any)=>e.nome===usuario?.empresa)||{};const titulo=tipo.includes('PGR')?'PGR - Programa de Gerenciamento de Riscos':tipo.includes('LTCAT')?'LTCAT - Laudo Técnico':tipo.includes('LIP')?'LIP - Laudo de Insalubridade':tipo.includes('PCMSO')?'PCMSO - Programa de Controle Médico':tipo;const cor=tipo.includes('PGR')?'#0d9488':tipo.includes('LTCAT')?'#2563eb':tipo.includes('LIP')?'#f59e0b':'#16a34a';let lr=riscos.length?riscos.map((r:any,i:number)=>'<tr><td>'+(i+1)+'</td><td>'+(r.ghe||'-')+'</td><td>'+(r.nome||'-')+'</td><td>'+(r.tipo||'-')+'</td><td>'+(r.agente||'-')+'</td><td>'+(r.epi||'EPI')+'</td></tr>').join(''):'<tr><td colspan="6">Nenhum risco cadastrado.</td></tr>';let lf=funcs.length?funcs.map((f:any)=>'<tr><td>'+(f.nome||'-')+'</td><td>'+(f.cargo||'-')+'</td><td>'+(f.setor||'-')+'</td><td>'+(f.cpf||'-')+'</td></tr>').join(''):'<tr><td colspan="4">Nenhum funcionário.</td></tr>';let corpo='<div class="card"><b>Dados da Empresa</b><div class="grid" style="margin-top:10px"><div><small>Empresa</small><br><b>'+(usuario?.empresa||tecnico.empresaLaudo||'-')+'</b></div><div><small>CNPJ</small><br><b>'+(empObj.cnpj||tecnico.cnpj||'-')+'</b></div><div><small>Responsável</small><br><b>'+tecnico.nome+' - '+tecnico.formacao+'</b></div><div><small>Contato</small><br><b>'+(tecnico.telefone||'(82) 99414-5622')+'</b></div></div></div><div class="nota">Documento elaborado conforme NR-01, NR-09, NR-07. Revisar anualmente ou após mudança de processo.</div><h3>1. Inventário de Riscos</h3><table><tr><th>#</th><th>GHE</th><th>Risco</th><th>Tipo</th><th>Agente</th><th>Controle</th></tr>'+lr+'</table><h3>2. Funcionários</h3><table><tr><th>Nome</th><th>Cargo</th><th>Setor</th><th>CPF</th></tr>'+lf+'</table>';abrirLaudo(pdfBase(titulo,'Laudo oficial PREVIX SST',cor,corpo))}
function gerarRelatorioExtintores(){const exts=dadosFiltrados(dados.extintores||[]);const qV=exts.filter((e:any)=>statusExtintor(e).label.includes('VENCIDO')).length;const qA=exts.filter((e:any)=>statusExtintor(e).label.includes('A VENCER')).length;const qD=exts.filter((e:any)=>statusExtintor(e).label.includes('EM DIA')).length;let linhas=exts.length?exts.map((e:any,i:number)=>{const st=statusExtintor(e);const bg=st.label.includes('VENCIDO')?'#fee2e2':st.label.includes('A VENCER')?'#fef3c7':'#dcfce7';return '<tr><td>'+(i+1)+'</td><td><b>'+(e.localizacao||'-')+'</b><br><small>'+(e.tipo||'-')+'</small></td><td>'+fmtData(e.vencimento)+'</td><td>'+fmtData(e.ultima_recarga)+'</td><td><span class="badge" style="background:'+bg+'">'+st.emoji+' '+st.label+'</span></td></tr>'}).join(''):'<tr><td colspan="5">Nenhum extintor.</td></tr>';let corpo='<div class="card"><b>Resumo NR-23</b><div class="grid" style="margin-top:10px"><div><small>Total</small><br><b>'+exts.length+'</b></div><div><small>Em Dia</small><br><b>'+qD+'</b></div><div><small>A Vencer</small><br><b>'+qA+'</b></div><div><small>Vencidos</small><br><b>'+qV+'</b></div></div></div><table><tr><th>#</th><th>Local / Tipo</th><th>Vencimento</th><th>Recarga</th><th>Status</th></tr>'+linhas+'</table>';abrirLaudo(pdfBase('Relatório de Extintores - NR-23','Relatório para fiscalização','#dc2626',corpo))}
function gerarRelatorioDocumentos(){const docs=dadosFiltrados(dados.documentos||[]);const qV=docs.filter((e:any)=>statusDoc(e).label.includes('VENCIDO')).length;const qA=docs.filter((e:any)=>statusDoc(e).label.includes('A VENCER')).length;const qD=docs.filter((e:any)=>statusDoc(e).label.includes('EM DIA')).length;let linhas=docs.length?docs.map((d:any,i:number)=>{const st=statusDoc(d);return '<tr><td>'+(i+1)+'</td><td><b>'+(d.titulo||'-')+'</b><br><small>'+(d.nomeArquivo||'Sem arquivo')+'</small></td><td>'+(d.pasta||d.tipo||'-')+'</td><td>'+fmtData(d.vencimento)+'</td><td>'+st.emoji+' '+st.label+'</td></tr>'}).join(''):'<tr><td colspan="5">Nenhum documento.</td></tr>';let corpo='<div class="card"><b>Resumo</b><div class="grid" style="margin-top:10px"><div><small>Total</small><br><b>'+docs.length+'</b></div><div><small>Em Dia</small><br><b>'+qD+'</b></div><div><small>A Vencer</small><br><b>'+qA+'</b></div><div><small>Vencidos</small><br><b>'+qV+'</b></div></div></div><table><tr><th>#</th><th>Documento</th><th>Pasta</th><th>Vencimento</th><th>Status</th></tr>'+linhas+'</table>';abrirLaudo(pdfBase('Relatório de Documentos','Controle de vencimentos','#0f172a',corpo))}
function gerarRelatorioExames(){const exs=dadosFiltrados(dados.exames||[]);const qV=exs.filter((e:any)=>statusExame(e)==='vencido').length;const qR=exs.filter((e:any)=>statusExame(e)==='realizado').length;const qF=exs.filter((e:any)=>statusExame(e)==='futuro'||statusExame(e)==='hoje').length;let linhas=exs.length?exs.map((e:any,i:number)=>{const st=statusExame(e);const label=st==='vencido'?'VENCIDO':st==='realizado'?'REALIZADO':st==='hoje'?'HOJE':'AGENDADO';return '<tr><td>'+(i+1)+'</td><td><b>'+(e.nome||'-')+'</b></td><td>'+(e.tipo||'-')+'</td><td>'+fmtData(e.data)+'</td><td>'+(e.clinica||'-')+'</td><td>'+label+'</td></tr>'}).join(''):'<tr><td colspan="6">Nenhum exame.</td></tr>';let corpo='<div class="card"><b>Resumo PCMSO</b><div class="grid" style="margin-top:10px"><div><small>Total</small><br><b>'+exs.length+'</b></div><div><small>Realizados</small><br><b>'+qR+'</b></div><div><small>Agendados</small><br><b>'+qF+'</b></div><div><small>Vencidos</small><br><b>'+qV+'</b></div></div></div><table><tr><th>#</th><th>Funcionário</th><th>Tipo</th><th>Data</th><th>Clínica</th><th>Status</th></tr>'+linhas+'</table>';abrirLaudo(pdfBase('Relatório de Exames - PCMSO','Controle de exames','#2563eb',corpo))}
function gerarRelatorioInspecao(item:any){const empNome=item.empresa||usuario?.empresa||'Empresa';const checklist=item.checklist||[];const qC=checklist.filter((c:any)=>c.status==='Conforme').length;const qNC=checklist.filter((c:any)=>c.status==='Não Conforme').length;let lc=checklist.length?checklist.map((c:any,i:number)=>'<tr><td>'+(i+1)+'</td><td><b>'+c.item+'</b>'+(c.obs?'<br><small>Obs: '+c.obs+'</small>':'')+'</td><td>'+(c.status||'N/A')+'</td></tr>').join(''):'<tr><td colspan="3">Sem itens.</td></tr>';let fh=(item.fotos||[]).length?(item.fotos||[]).map((f:string)=>'<img src="'+f+'" style="width:220px;height:150px;object-fit:cover;margin:6px;border-radius:12px" />').join(''):'<p>Sem fotos.</p>';let corpo='<div class="card"><b>Dados da Inspeção</b><div class="grid" style="margin-top:10px"><div><small>Empresa</small><br><b>'+empNome+'</b></div><div><small>Local</small><br><b>'+(item.local||'-')+'</b></div><div><small>Data</small><br><b>'+fmtData(item.data)+'</b></div><div><small>Tipo</small><br><b>'+(item.tipoInspecao||item.tipo||'-')+'</b></div><div><small>Motivo</small><br><b>'+(item.motivo||'-')+'</b></div><div><small>Resultado</small><br><b>Conforme: '+qC+' • Não Conforme: '+qNC+'</b></div></div></div><div class="card"><b>Objetivo:</b> '+(item.objetivo||'Verificar condições de segurança.')+'<br><br><b>Achados:</b> '+(item.observacoes||'Sem observações.')+'</div><h3>Checklist</h3><table><tr><th>#</th><th>Item</th><th>Resultado</th></tr>'+lc+'</table><h3>Ações</h3><div class="card"><b>Não Conformidades:</b> '+(item.naoConformidades||'Nenhuma.')+'<br><br><b>Ação Imediata:</b> '+(item.acaoImediata||'-')+'<br><br><b>Ação Longo Prazo:</b> '+(item.acaoLongoPrazo||'-')+'<br><br><b>Conclusão:</b> '+(item.conclusao||'Concluída.')+'</div><h3>Fotos</h3><div>'+fh+'</div>';abrirLaudo(pdfBase('Laudo de Inspeção de Segurança','Inspeção técnica','#0f172a',corpo))}
function gerarTermo(e:any){const func=(dados.funcionarios||[]).find((f:any)=>f.nome===e.funcionario)||{};const empNome=e.empresa||func.empresa||usuario?.empresa||'PREVIX SST';const empObj=(dados.empresas||[]).find((x:any)=>x.nome===empNome)||{};const dataFmt=e.data_entrega?e.data_entrega.split('-').reverse().join('/'):new Date().toLocaleDateString('pt-BR');const formas=[];if(e.pinVerificado)formas.push('PIN ✅');if(e.biometria)formas.push('Biometria ✅');if(e.assinaturaImg)formas.push('Assinatura ✅');let corpo='<div class="card"><b>Dados do Recebimento - NR-06</b><div class="grid" style="margin-top:10px"><div><small>Empresa</small><br><b>'+empNome+'</b></div><div><small>CNPJ</small><br><b>'+(empObj.cnpj||tecnico.cnpj||'-')+'</b></div><div><small>Funcionário</small><br><b>'+(e.funcionario||'-')+'</b></div><div><small>CPF</small><br><b>'+(func.cpf||'-')+'</b></div><div><small>Cargo / Setor</small><br><b>'+(func.cargo||'-')+' • '+(func.setor||'-')+'</b></div><div><small>Data</small><br><b>'+dataFmt+'</b></div></div></div><h3>EPI Entregue</h3><table><tr><th>EPI</th><th>Tipo</th><th>CA</th><th>Qtd</th><th>Data</th></tr><tr><td><b>'+iconeEpi(e.nome)+' '+(e.nome||'-')+'</b></td><td>'+(e.tipo||'-')+'</td><td>'+(e.ca||'-')+'</td><td>'+(e.quantidade||1)+'</td><td>'+dataFmt+'</td></tr></table><div class="card"><b>Declaração:</b><br><br>Declaro que recebi o EPI acima, em perfeito estado, com CA válido. Comprometo-me a usar corretamente e comunicar dano ou extravio. Uso obrigatório conforme NR-06.<br><br><b>Confirmação:</b> '+(formas.length?formas.join(' • '):'Registro no sistema')+' • <b>PIN:</b> '+(func.pin||'-')+'</div>'+(e.assinaturaImg?'<div class="card" style="text-align:center"><b>Assinatura</b><br><img src="'+e.assinaturaImg+'" style="max-width:320px;max-height:120px;margin-top:10px" /></div>':'<div class="card" style="text-align:center;color:#64748b">Assinatura registrada por PIN / Biometria no sistema PREVIX SST</div>');abrirLaudo(pdfBase('Termo de Entrega de EPI - NR-06','Comprovante de entrega','#0d9488',corpo))}
function fazerLogin(){setErroLogin('');const login=loginForm.login.trim().toLowerCase();const senha=loginForm.senha.trim();const adm=getAdmin();if(login===adm.login&&senha===adm.senha){setUsuario(adm);localStorage.setItem('previx_session',JSON.stringify(adm));setAba('inicio');return}if(login==='admin'&&senha==='admin'){setUsuario(adm);localStorage.setItem('previx_session',JSON.stringify(adm));setAba('inicio');return}const emp=(dados.empresas||[]).find((e:any)=>(e.login||'').toLowerCase()===login&&(e.senha||'')===senha);if(emp){const u={login:emp.login,nome:emp.responsavel||emp.nome,tipo:'empresa',empresa:emp.nome};setUsuario(u);localStorage.setItem('previx_session',JSON.stringify(u));setAba('inicio');return}setErroLogin('Login ou senha incorretos!')}
function sair(){setUsuario(null);localStorage.removeItem('previx_session');setLoginForm({login:'',senha:''});setAba('inicio')}
function abrirNovo(){setEditando(null);setForm({});setMetodo('');setPinDigitado('');setPinVerificado(false);setAssinaturaFeita(false);setBioStatus('aguardando');setBioMsg('');if(aba==='empresas')setForm({senha:gerarSenha(),status:'Ativa',dicaSenha:''});if(aba==='funcionarios')setForm({empresa:usuario?.tipo==='empresa'?usuario.empresa:'',pin:gerarPIN(),setor:'Vendas'});if(aba==='epis'){setForm({empresa:usuario?.tipo==='empresa'?usuario.empresa:'',data_entrega:new Date().toISOString().split('T')[0],quantidade:1,tipo:'',modelo:''});setTimeout(()=>{const c=canvasRef.current;if(c){const ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height)}},100)}if(aba==='exames'){setForm({data:diaSel,clinica:clinicaSel,tipo:'Periódico',resultado:'Pendente',empresa:usuario?.tipo==='empresa'?usuario.empresa:'',nome:''})}if(aba==='inspecoes'){const tipo0='Visita Técnica Geral';const itens0=TIPOS_INSPECAO.find(t=>t.id===tipo0)?.itens||[];setForm({empresa:usuario?.tipo==='empresa'?usuario.empresa:'',status:'Realizada',data:new Date().toISOString().split('T')[0],tipoInspecao:tipo0,tipo:tipo0,motivo:'Rotina Periódica',checklist:itens0.map(it=>({item:it,status:'Conforme',obs:''})),observacoes:'',naoConformidades:'',acaoImediata:'',acaoLongoPrazo:'',conclusao:'',objetivo:'',fotos:[],cnpjEmpresa:'',enderecoEmpresa:''})}if(aba==='riscos')setForm({ghe:'Vendas',tipo:'Físico',nome:'',agente:'',limite:'',epi:''});if(aba==='financeiro')setForm({status:'Pendente',vencimento:new Date().toISOString().split('T')[0]});if(aba==='clinicas')setForm({status:'Ativa',convenio:'Vigente',cnpj:''});if(aba==='extintores')setForm({empresa:usuario?.tipo==='empresa'?usuario.empresa:'',tipo:'PQS 6kg',vencimento:new Date().toISOString().split('T')[0]});setModal(true)}
function abrirEditar(item:any){setEditando(item);setForm({...item});setPinDigitado('');setPinVerificado(!!item.pinVerificado);setAssinaturaFeita(!!item.assinaturaImg);setBioStatus(item.biometria?'ok':'aguardando');setBioMsg(item.biometria||'');if(item.pinVerificado)setMetodo('pin');else if(item.biometria)setMetodo('digital');else if(item.assinaturaImg)setMetodo('assinatura');else setMetodo('');setModal(true)}
function verificarPIN(){const func=(dados.funcionarios||[]).find((f:any)=>f.nome===form.funcionario)||(dados.funcionarios||[]).find((f:any)=>(f.cpf||'')===form.funcionario);if(!func){alert('Primeiro escolhe o funcionário!');return}if(metodo!=='pin'){alert('Primeiro escolhe o método PIN!');return}if(pinDigitado===String(func.pin)){setPinVerificado(true);alert('✅ PIN correto!')}else{setPinVerificado(false);alert('❌ PIN incorreto.')}}
function iniciarDigital(){if(!form.funcionario){alert('Primeiro escolhe o funcionário!');return}if(metodo!=='digital'){alert('Primeiro escolhe o método Digital!');return}setBioStatus('lendo');setBioMsg('Coloque o dedo do funcionário no leitor...')}
function confirmarDigitalOK(){setBioStatus('ok');setBioMsg('✅ Digital conferida - é do funcionário '+form.funcionario)}
function recusarDigital(){setBioStatus('recusada');setBioMsg('❌ Digital recusada - NÃO é do funcionário.');setTimeout(()=>{setBioStatus('aguardando');setBioMsg('')},2500)}
function limparAssinatura(){const c=canvasRef.current;if(c){const ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height)}setAssinaturaFeita(false)}
function posCanvas(e:any){const c=canvasRef.current;const r=c.getBoundingClientRect();const t=e.touches?.[0]||e;return{x:t.clientX-r.left,y:t.clientY-r.top}}
function subirFotoExtintor(e:any){const file=e.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>setForm({...form,foto:reader.result});reader.readAsDataURL(file)}
function subirDoc(e:any){const file=e.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>setForm({...form,arquivo:reader.result,nomeArquivo:file.name,tipoArquivo:file.type,titulo:form.titulo||file.name.replace(/\.[^/.]+$/,'')});reader.readAsDataURL(file)}
function subirFotoInspecao(e:any){const files=Array.from(e.target.files||[]);files.forEach((file:any)=>{const reader=new FileReader();reader.onload=()=>setForm((prev:any)=>({...prev,fotos:[...(prev.fotos||[]),reader.result]}));reader.readAsDataURL(file)})}
function baixarDoc(item:any){if(!item.arquivo){alert('Sem arquivo.');return}const a=document.createElement('a');a.href=item.arquivo;a.download=item.nomeArquivo||(item.titulo+'.pdf');a.click()}
function salvar(){if(!aba||aba==='inicio')return;const f={...form};if(aba==='funcionarios'){if(!f.pin)f.pin=gerarPIN();if(!f.nome){alert('Coloca o nome!');return}if(!f.setor)f.setor='Vendas'}if(aba==='exames'){if(!f.nome){alert('Escolhe o funcionário!');return}f.data=limparData(f.data)||new Date().toISOString().split('T')[0];f.funcionario=f.nome;if(!f.clinica)f.clinica=clinicaSel}if(aba==='epis'){if(!f.nome){alert('Escolhe o EPI!');return}if(!f.funcionario){alert('Digita nome OU CPF!');return}if(!metodo){alert('Escolhe como vai assinar: PIN OU Digital OU Assinatura');return}if(metodo==='pin'&&!pinVerificado){alert('Você escolheu PIN. Digita o PIN e clica em Verificar PIN.');return}if(metodo==='digital'&&bioStatus!=='ok'){alert('Você escolheu Digital. Coloque o dedo e confirme que é a digital do funcionário.');return}if(metodo==='assinatura'&&!assinaturaFeita){alert('Você escolheu Assinatura. Assina no quadro antes de salvar.');return}const c=canvasRef.current;f.assinaturaImg=(metodo==='assinatura'&&assinaturaFeita&&c)?c.toDataURL():f.assinaturaImg||'';f.pinVerificado=metodo==='pin'&&pinVerificado;f.biometria=metodo==='digital'&&bioStatus==='ok'?(bioMsg||'Biometria OK'):'';f.quantidade=f.quantidade||1;f.formaConfirmacao=metodo==='pin'?'PIN':metodo==='digital'?'Digital':'Assinatura';f.metodoConfirmacao=metodo}if(aba==='inspecoes'){if(!f.titulo){alert('Coloca o título!');return}if(!f.tipoInspecao)f.tipoInspecao='Visita Técnica Geral';f.tipo=f.tipoInspecao;if(f.cnpjEmpresa)f.cnpjEmpresa=mascaraCNPJ(f.cnpjEmpresa);if(!f.checklist||!f.checklist.length){const itens=TIPOS_INSPECAO.find(t=>t.id===f.tipoInspecao)?.itens||['Item 1'];f.checklist=itens.map((it:string)=>({item:it,status:'Conforme',obs:''}))}}if(aba==='extintores'){if(!f.localizacao&&!f.nome){alert('Coloca a localização!');return}if(!f.vencimento){alert('Coloca o vencimento!');return}f.nome=f.localizacao||f.nome||'Extintor'}if(aba==='documentos'){if(!f.titulo){alert('Coloca o título!');return}if(!f.pasta)f.pasta='PGR';f.tipo=f.pasta}if(aba==='clinicas'){if(!f.nome){alert('Coloca o nome!');return}if(f.cnpj)f.cnpj=mascaraCNPJ(f.cnpj)}if(aba==='empresas'){if(!f.login&&f.nome)f.login=f.nome.toLowerCase().replace(/[^a-z0-9]/g,'').slice(0,12);if(!f.senha)f.senha=gerarSenha();if(f.cnpj)f.cnpj=mascaraCNPJ(f.cnpj)}if(aba==='riscos'&&!f.nome){alert('Aperta um risco: Ruído, Poeira, etc.!');return}if(aba==='financeiro'&&!f.descricao){alert('Descrição!');return}if(usuario?.tipo==='empresa')f.empresa=usuario.empresa;const lista=[...(dados[aba]||[])];if(editando){const id=editando.id||editando._id;const idx=lista.findIndex((x:any)=>(x.id||x._id)===id);if(idx>=0)lista[idx]={...lista[idx],...f};const nd={...dados,[aba]:lista};setDados(nd);salvarNav(nd)}else{const novo={...f,id:Date.now().toString(),status:f.status||'Ativa'};lista.push(novo);const nd={...dados,[aba]:lista};setDados(nd);salvarNav(nd);if(aba==='funcionarios')alert('✅ '+novo.nome+' • PIN: '+novo.pin);if(aba==='epis')alert('✅ Entrega confirmada por '+f.formaConfirmacao)}setModal(false);setForm({});setEditando(null);setMetodo('')}
function excluir(item:any){if(!confirm('Excluir '+(item.nome||item.titulo||item.descricao||'registro')+'?'))return;const id=item.id||item._id;const nl=(dados[aba]||[]).filter((x:any)=>(x.id||x._id)!==id);const nd={...dados,[aba]:nl};setDados(nd);salvarNav(nd)}
function confirmarAgendamento(){if(!funcAgend){alert('Escolhe o funcionário!');return}if(tiposSel.length===0){alert('Marca 1 tipo!');return}const novos=tiposSel.map(t=>{return{id:Date.now().toString()+Math.random().toString().slice(2,6),nome:funcAgend,funcionario:funcAgend,tipo:t,data:diaSel,clinica:clinicaSel,empresa:usuario?.tipo==='empresa'?usuario.empresa:'',resultado:'Pendente'}});const nd={...dados,exames:[...(dados.exames||[]),...novos]};setDados(nd);salvarNav(nd);alert('✅ Agendado! '+funcAgend+' • '+clinicaSel+' • '+fmtData(diaSel));setTiposSel([]);setFuncAgend('')}
function mudarMes(delta:number){const [y,m]=diaSel.split('-').map(Number);const dt=new Date(y,m-1+delta,1);setDiaSel(dt.getFullYear()+'-'+String(dt.getMonth()+1).padStart(2,'0')+'-01')}
function salvarSenhaCliente(emp:any,nova:string,dica:string){if(!nova||nova.length<4){alert('Senha mínimo 4 caracteres!');return}const lista=(dados.empresas||[]).map((e:any)=>e.id===emp.id?{...e,senha:nova,dicaSenha:dica}:e);const nd={...dados,empresas:lista};setDados(nd);salvarNav(nd);alert('✅ Senha de '+emp.nome+' trocada! Nova: '+nova);setSenhaClienteTemp({})}
